import { WebhooksPage } from "@/modules/integrations/webhooks/page";
import { getSettingsPageMetadata } from "@/modules/settings/lib/metadata";

export const generateMetadata = () => getSettingsPageMetadata("common.webhooks");

export default WebhooksPage;

"use client";

import { type JSX, useState } from "react";
import { useTranslation } from "react-i18next";
import { Webhook } from "@formbricks/database/prisma-browser";
import { TSurvey } from "@formbricks/types/surveys/types";
import { WebhookModal } from "@/modules/integrations/webhooks/components/webhook-detail-modal";
import { EmptyState } from "@/modules/ui/components/empty-state";

interface WebhookTableProps {
  workspaceId: string;
  webhooks: Webhook[];
  surveys: TSurvey[];
  children: [JSX.Element, JSX.Element[]];
  isReadOnly: boolean;
  allowInternalUrls: boolean;
  surveyVisibilityEnabled: boolean;
}

export const WebhookTable = ({
  workspaceId,
  webhooks,
  surveys,
  children: [TableHeading, webhookRows],
  isReadOnly,
  allowInternalUrls,
  surveyVisibilityEnabled,
}: Readonly<WebhookTableProps>) => {
  const [isWebhookDetailModalOpen, setWebhookDetailModalOpen] = useState(false);
  const { t } = useTranslation();
  const [activeWebhook, setActiveWebhook] = useState<Webhook>({
    workspaceId,
    id: "",
    name: "",
    url: "",
    source: "user",
    triggers: [],
    surveyIds: [],
    createdAt: new Date(),
    updatedAt: new Date(),
    secret: null,
  });

  const handleOpenWebhookDetailModalClick = (e: React.MouseEvent, webhook: Webhook) => {
    e.preventDefault();
    setActiveWebhook(webhook);
    setWebhookDetailModalOpen(true);
  };

  return (
    <>
      {webhooks.length === 0 ? (
        <EmptyState text={t("workspace.integrations.webhooks.empty_webhook_message")} />
      ) : (
        <div className="rounded-lg border border-slate-200">
          {TableHeading}
          <div className="grid-cols-7">
            {webhooks.map((webhook, index) => (
              <button
                type="button"
                onClick={(e) => {
                  handleOpenWebhookDetailModalClick(e, webhook);
                }}
                className="w-full"
                key={webhook.id}>
                {webhookRows[index]}
              </button>
            ))}
          </div>
        </div>
      )}
      <WebhookModal
        open={isWebhookDetailModalOpen}
        setOpen={setWebhookDetailModalOpen}
        webhook={activeWebhook}
        surveys={surveys}
        isReadOnly={isReadOnly}
        allowInternalUrls={allowInternalUrls}
        surveyVisibilityEnabled={surveyVisibilityEnabled}
      />
    </>
  );
};

"use client";

import { TFunction } from "i18next";
import { useTranslation } from "react-i18next";
import { Webhook } from "@formbricks/database/prisma-browser";
import { TSurvey } from "@formbricks/types/surveys/types";
import { timeSince } from "@/lib/time";
import { RestrictedSurveyHint } from "@/modules/survey/visibility/components/restricted-survey-hint";
import { hasRestrictedAttachedSurvey } from "@/modules/survey/visibility/lib/outbound";
import { Badge } from "@/modules/ui/components/badge";

const renderSelectedSurveysText = (webhook: Webhook, allSurveys: TSurvey[]) => {
  let surveyNames: string[];

  if (webhook.surveyIds.length === 0) {
    surveyNames = allSurveys.map((survey) => survey.name);
  } else {
    surveyNames = webhook.surveyIds
      .map((surveyId) => {
        const survey = allSurveys.find((s) => s.id === surveyId);
        return survey ? survey.name : "";
      })
      .filter(Boolean);
  }

  if (surveyNames.length === 0) {
    return <p className="text-slate-400">-</p>;
  }

  return (
    <p className="truncate text-slate-400" title={surveyNames.join(", ")}>
      {surveyNames.join(", ")}
    </p>
  );
};

const renderSelectedTriggersText = (webhook: Webhook, t: TFunction) => {
  if (webhook.triggers.length === 0) {
    return <p className="text-slate-400">{t("workspace.integrations.webhooks.no_triggers")}</p>;
  } else {
    let cleanedTriggers = webhook.triggers.map((trigger) => {
      if (trigger === "responseCreated") {
        return t("workspace.integrations.webhooks.response_created");
      } else if (trigger === "responseUpdated") {
        return t("workspace.integrations.webhooks.response_updated");
      } else if (trigger === "responseFinished") {
        return t("workspace.integrations.webhooks.response_finished");
      } else {
        return trigger;
      }
    });

    return (
      <p className="text-slate-400">
        {cleanedTriggers
          .sort((a, b) => {
            const triggerOrder = {
              "Response Created": 1,
              "Response Updated": 2,
              "Response Finished": 3,
            };

            return (triggerOrder as Record<string, number>)[a] - (triggerOrder as Record<string, number>)[b];
          })
          .join(", ")}
      </p>
    );
  }
};

export const WebhookRowData = ({
  webhook,
  surveys,
  surveyVisibilityEnabled,
}: Readonly<{ webhook: Webhook; surveys: TSurvey[]; surveyVisibilityEnabled: boolean }>) => {
  const { t, i18n } = useTranslation();
  const locale = i18n.resolvedLanguage ?? i18n.language ?? "en-US";

  return (
    <div className="mt-2 grid h-auto grid-cols-12 content-center rounded-lg py-2 hover:bg-slate-100">
      <div className="col-span-3 flex items-center truncate pl-6 text-sm">
        <div className="flex items-center">
          <div className="text-left">
            {webhook.name ? (
              <div className="text-left">
                <div className="font-medium text-slate-900">{webhook.name}</div>
                <div className="text-xs text-slate-400">{webhook.url}</div>
              </div>
            ) : (
              <div className="font-medium text-slate-900">{webhook.url}</div>
            )}
          </div>
        </div>
      </div>
      <div className="col-span-1 my-auto text-center text-sm text-slate-800">
        <Badge type="gray" size="tiny" text={webhook.source || t("common.user")} className="capitalize" />
      </div>
      <div className="col-span-4 my-auto flex min-w-0 items-center justify-center gap-x-2 text-sm text-slate-800">
        {renderSelectedSurveysText(webhook, surveys)}
        {hasRestrictedAttachedSurvey(surveyVisibilityEnabled, webhook.surveyIds, surveys) && (
          <RestrictedSurveyHint kind="paused" />
        )}
      </div>
      <div className="col-span-2 my-auto text-center text-sm text-slate-800">
        {renderSelectedTriggersText(webhook, t)}
      </div>
      <div className="col-span-2 my-auto text-center text-sm whitespace-nowrap text-slate-500">
        {timeSince(webhook.updatedAt.toString(), locale)}
      </div>
      <div className="text-center"></div>
    </div>
  );
};

import { NextRequest } from "next/server";
import { findNotWorkspaceVisibleSurveyIds } from "@/lib/survey/visibility/outbound";
import { authenticatedApiClient } from "@/modules/api/v2/auth/authenticated-api-client";
import { responses } from "@/modules/api/v2/lib/response";
import { handleApiError } from "@/modules/api/v2/lib/utils";
import { getAuthorizedApiKeyWorkspaceIds } from "@/modules/api/v2/management/lib/authorized-workspace-ids";
import { getWorkspaceIdFromSurveyIds } from "@/modules/api/v2/management/lib/helper";
import { surveyNotWorkspaceVisibleError } from "@/modules/api/v2/management/lib/survey-visibility";
import { resolveBodyIdsV2 } from "@/modules/api/v2/management/lib/workspace-resolver";
import { createWebhook, getWebhooks } from "@/modules/api/v2/management/webhooks/lib/webhook";
import { ZGetWebhooksFilter, ZWebhookCreateInput } from "@/modules/api/v2/management/webhooks/types/webhooks";

export const GET = async (request: NextRequest) =>
  authenticatedApiClient({
    request,
    schemas: {
      query: ZGetWebhooksFilter,
    },
    handler: async ({ authentication, parsedInput }) => {
      const { query } = parsedInput;

      if (!query) {
        return handleApiError(request, {
          type: "bad_request",
          details: [{ field: "query", issue: "missing" }],
        });
      }

      const workspaceIds = await getAuthorizedApiKeyWorkspaceIds(authentication);

      const res = await getWebhooks(workspaceIds, query);

      if (res.ok) {
        return responses.successResponse(res.data);
      }

      return handleApiError(request, res.error);
    },
  });

export const POST = async (request: NextRequest) =>
  authenticatedApiClient({
    request,
    schemas: {
      body: ZWebhookCreateInput,
    },
    bodyTransform: async (body, auth) => {
      const resolved = await resolveBodyIdsV2(body, auth, "POST");
      if (!resolved.ok) throw resolved.error;
      return { ...body, ...resolved.data };
    },
    handler: async ({ parsedInput, auditLog }) => {
      const { body } = parsedInput;

      if (!body) {
        return handleApiError(
          request,
          {
            type: "bad_request",
            details: [{ field: "body", issue: "missing" }],
          },
          auditLog
        );
      }

      if (body.surveyIds && body.surveyIds.length > 0) {
        const workspaceIdResult = await getWorkspaceIdFromSurveyIds(body.surveyIds);

        if (!workspaceIdResult.ok) {
          return handleApiError(request, workspaceIdResult.error, auditLog);
        }

        // The body's workspace is the one the key was authorized for; its surveys must be that
        // workspace's too, as the PUT already checks.
        if (workspaceIdResult.data !== body.workspaceId) {
          return handleApiError(
            request,
            {
              type: "bad_request",
              details: [
                { field: "surveyIds", issue: "webhook workspace does not match the surveys workspace" },
              ],
            },
            auditLog
          );
        }

        const blockedSurveyIds = await findNotWorkspaceVisibleSurveyIds(body.surveyIds);
        if (blockedSurveyIds.length > 0) {
          return handleApiError(request, surveyNotWorkspaceVisibleError(blockedSurveyIds), auditLog);
        }
      }

      const createWebhookResult = await createWebhook(body);

      if (!createWebhookResult.ok) {
        return handleApiError(request, createWebhookResult.error, auditLog);
      }

      if (auditLog) {
        auditLog.targetId = createWebhookResult.data.id;
        auditLog.newObject = createWebhookResult.data;
      }

      return responses.createdResponse(createWebhookResult);
    },
    action: "created",
    targetType: "webhook",
  });

import { prisma } from "@formbricks/database";
import { Prisma, Webhook } from "@formbricks/database/prisma";
import { Result, err, ok } from "@formbricks/types/error-handlers";
import { InvalidInputError } from "@formbricks/types/errors";
import { generateWebhookSecret } from "@/lib/crypto";
import { validateWebhookUrl } from "@/lib/utils/validate-webhook-url";
import { getWebhooksQuery } from "@/modules/api/v2/management/webhooks/lib/utils";
import { TGetWebhooksFilter, TWebhookInput } from "@/modules/api/v2/management/webhooks/types/webhooks";
import { ApiErrorResponseV2 } from "@/modules/api/v2/types/api-error";
import { ApiResponseWithMeta } from "@/modules/api/v2/types/api-success";

export const getWebhooks = async (
  workspaceIds: string[],
  params: TGetWebhooksFilter
): Promise<Result<ApiResponseWithMeta<Omit<Webhook, "secret">[]>, ApiErrorResponseV2>> => {
  try {
    const query = getWebhooksQuery(workspaceIds, params);

    const [webhooks, count] = await prisma.$transaction([
      prisma.webhook.findMany({
        ...query,
        omit: {
          secret: true,
        },
      }),
      prisma.webhook.count({
        where: query.where,
      }),
    ]);

    if (!webhooks) {
      return err({
        type: "not_found",
        details: [{ field: "webhooks", issue: "not_found" }],
      });
    }

    return ok({
      data: webhooks,
      meta: {
        total: count,
        limit: params?.limit,
        offset: params?.skip,
      },
    });
  } catch (error) {
    return err({
      type: "internal_server_error",
      details: [
        { field: "webhooks", issue: error instanceof Error ? error.message : "Unknown error occurred" },
      ],
    });
  }
};

export const createWebhook = async (webhook: TWebhookInput): Promise<Result<Webhook, ApiErrorResponseV2>> => {
  const { workspaceId, name, url, source, triggers, surveyIds } = webhook;

  try {
    await validateWebhookUrl(url);
  } catch (error) {
    if (error instanceof InvalidInputError) {
      return err({
        type: "bad_request",
        details: [{ field: "url", issue: error.message }],
      });
    }
    return err({
      type: "internal_server_error",
      details: [{ field: "url", issue: "Webhook URL validation failed unexpectedly" }],
    });
  }

  try {
    const secret = generateWebhookSecret();

    const prismaData: Prisma.WebhookCreateInput = {
      workspace: {
        connect: {
          id: workspaceId,
        },
      },
      name,
      url,
      source,
      triggers,
      surveyIds,
      secret,
    };

    const createdWebhook = await prisma.webhook.create({
      data: prismaData,
    });

    return ok(createdWebhook);
  } catch (error) {
    return err({
      type: "internal_server_error",
      details: [
        { field: "webhook", issue: error instanceof Error ? error.message : "Unknown error occurred" },
      ],
    });
  }
};

import { z } from "zod";
import { ZWebhook } from "@formbricks/database/zod/webhooks";
import { ZGetFilter } from "@/modules/api/v2/types/api-filter";

export const ZGetWebhooksFilter = ZGetFilter.extend({
  surveyIds: z.array(z.cuid2()).optional(),
}).refine(
  (data) => {
    if (data.startDate && data.endDate && data.startDate > data.endDate) {
      return false;
    }
    return true;
  },
  {
    message: "startDate must be before endDate",
  }
);

export type TGetWebhooksFilter = z.infer<typeof ZGetWebhooksFilter>;

export const ZWebhookInput = ZWebhook.pick({
  name: true,
  url: true,
  source: true,
  workspaceId: true,
  triggers: true,
  surveyIds: true,
});

export type TWebhookInput = z.infer<typeof ZWebhookInput>;

// Route-level schema — workspaceId is required.
export const ZWebhookCreateInput = ZWebhook.pick({
  name: true,
  url: true,
  source: true,
  triggers: true,
  surveyIds: true,
}).extend({
  workspaceId: z.cuid2(),
});

export type TWebhookCreateInput = z.infer<typeof ZWebhookCreateInput>;

import { getTranslate } from "@/lingodotdev/server";

export const WebhookTableHeading = async () => {
  const t = await getTranslate();
  return (
    <>
      <div className="grid h-12 grid-cols-12 content-center rounded-lg bg-slate-100 text-left text-sm font-semibold text-slate-900">
        <span className="sr-only">{t("common.edit")}</span>
        <div className="col-span-3 pl-6">{t("common.webhook")}</div>
        <div className="col-span-1 text-center">{t("workspace.integrations.webhooks.source")}</div>
        <div className="col-span-4 text-center">{t("common.surveys")}</div>
        <div className="col-span-2 text-center">{t("workspace.integrations.webhooks.triggers")}</div>
        <div className="col-span-2 text-center">{t("common.updated")}</div>
      </div>
    </>
  );
};

"use server";

import { z } from "zod";
import { ZId } from "@formbricks/types/common";
import { ResourceNotFoundError } from "@formbricks/types/errors";
import { assertCan } from "@/lib/authorization";
import { generateWebhookSecret } from "@/lib/crypto";
import { capturePostHogEvent } from "@/lib/posthog";
import { assertNewlyAttachedSurveysWorkspaceVisible } from "@/lib/survey/visibility/outbound";
import { authenticatedActionClient } from "@/lib/utils/action-client";
import {
  getOrganizationIdFromWebhookId,
  getOrganizationIdFromWorkspaceId,
  getWorkspaceIdFromWebhookId,
} from "@/lib/utils/helper";
import {
  getWebhook,
  getWebhookWithSecret,
} from "@/modules/api/v2/management/webhooks/[webhookId]/lib/webhook";
import { applyRateLimit } from "@/modules/core/rate-limit/helpers";
import { rateLimitConfigs } from "@/modules/core/rate-limit/rate-limit-configs";
import { withAuditLogging } from "@/modules/ee/audit-logs/lib/handler";
import {
  createWebhook,
  deleteWebhook,
  testEndpoint,
  updateWebhook,
} from "@/modules/integrations/webhooks/lib/webhook";
import { ZWebhookInput } from "@/modules/integrations/webhooks/types/webhooks";

const ZCreateWebhookAction = z.object({
  workspaceId: ZId,
  webhookInput: ZWebhookInput,
  webhookSecret: z.string().optional(),
});

export const createWebhookAction = authenticatedActionClient.inputSchema(ZCreateWebhookAction).action(
  withAuditLogging("created", "webhook", async ({ ctx, parsedInput }) => {
    const organizationId = await getOrganizationIdFromWorkspaceId(parsedInput.workspaceId);
    await assertCan({ type: "user", id: ctx.user.id }, "workspace.write", {
      type: "workspace",
      id: parsedInput.workspaceId,
    });
    await applyRateLimit(rateLimitConfigs.actions.stateMutation, parsedInput.workspaceId);
    await assertNewlyAttachedSurveysWorkspaceVisible(parsedInput.webhookInput.surveyIds ?? []);
    const webhook = await createWebhook(
      parsedInput.workspaceId,
      parsedInput.webhookInput,
      parsedInput.webhookSecret
    );
    ctx.auditLoggingCtx.organizationId = organizationId;
    ctx.auditLoggingCtx.newObject = parsedInput.webhookInput;

    capturePostHogEvent(
      ctx.user.id,
      "integration_connected",
      {
        integration_type: "webhook",
        organization_id: organizationId,
        workspace_id: parsedInput.workspaceId,
      },
      { organizationId, workspaceId: parsedInput.workspaceId }
    );

    return webhook;
  })
);

const ZDeleteWebhookAction = z.object({
  id: ZId,
});

export const deleteWebhookAction = authenticatedActionClient.inputSchema(ZDeleteWebhookAction).action(
  withAuditLogging("deleted", "webhook", async ({ ctx, parsedInput }) => {
    const organizationId = await getOrganizationIdFromWebhookId(parsedInput.id);
    const workspaceId = await getWorkspaceIdFromWebhookId(parsedInput.id);
    await assertCan({ type: "user", id: ctx.user.id }, "workspace.write", {
      type: "workspace",
      id: workspaceId,
    });
    await applyRateLimit(rateLimitConfigs.actions.stateMutation, workspaceId);

    ctx.auditLoggingCtx.organizationId = organizationId;
    ctx.auditLoggingCtx.webhookId = parsedInput.id;
    ctx.auditLoggingCtx.oldObject = { ...(await getWebhook(parsedInput.id)) };

    const result = await deleteWebhook(parsedInput.id);
    return result;
  })
);

const ZUpdateWebhookAction = z.object({
  webhookId: ZId,
  webhookInput: ZWebhookInput,
});

export const updateWebhookAction = authenticatedActionClient.inputSchema(ZUpdateWebhookAction).action(
  withAuditLogging("updated", "webhook", async ({ ctx, parsedInput }) => {
    const organizationId = await getOrganizationIdFromWebhookId(parsedInput.webhookId);
    const workspaceId = await getWorkspaceIdFromWebhookId(parsedInput.webhookId);
    await assertCan({ type: "user", id: ctx.user.id }, "workspace.write", {
      type: "workspace",
      id: workspaceId,
    });
    await applyRateLimit(rateLimitConfigs.actions.stateMutation, workspaceId);

    ctx.auditLoggingCtx.organizationId = organizationId;
    ctx.auditLoggingCtx.webhookId = parsedInput.webhookId;
    const existing = await getWebhook(parsedInput.webhookId);
    ctx.auditLoggingCtx.oldObject = existing;
    await assertNewlyAttachedSurveysWorkspaceVisible(
      parsedInput.webhookInput.surveyIds ?? [],
      existing.ok ? existing.data.surveyIds : []
    );

    const result = await updateWebhook(parsedInput.webhookId, parsedInput.webhookInput);
    ctx.auditLoggingCtx.newObject = await getWebhook(parsedInput.webhookId);
    return result;
  })
);

const ZTestEndpointAction = z.object({
  url: z.string(),
  webhookId: ZId.optional(),
  // Required so the not-yet-created-webhook path has something to authorize against; without it this
  // action did no authorization at all and any logged-in user — including a billing-only member with no
  // product access — could make the server POST a signed test payload to any URL they named.
  workspaceId: ZId,
  secret: z.string().optional(),
});

export const testEndpointAction = authenticatedActionClient
  .inputSchema(ZTestEndpointAction)
  .action(async ({ ctx, parsedInput }) => {
    let secret: string | undefined;

    if (parsedInput.webhookId) {
      await assertCan({ type: "user", id: ctx.user.id }, "workspace.write", {
        type: "workspace",
        id: await getWorkspaceIdFromWebhookId(parsedInput.webhookId),
      });

      const webhookResult = await getWebhookWithSecret(parsedInput.webhookId);
      if (!webhookResult.ok) {
        throw new ResourceNotFoundError("Webhook", parsedInput.webhookId);
      }

      secret = webhookResult.data.secret ?? undefined;
    } else {
      // No webhook yet: authorize against the workspace the webhook is being created in.
      await assertCan({ type: "user", id: ctx.user.id }, "workspace.write", {
        type: "workspace",
        id: parsedInput.workspaceId,
      });

      // New webhook, use the provided secret or generate a new one
      secret = parsedInput.secret ?? generateWebhookSecret();
    }

    await testEndpoint(parsedInput.url, secret);
    return { success: true, secret };
  });

import { DANGEROUSLY_ALLOW_WEBHOOK_INTERNAL_URLS } from "@/lib/constants";
import { getTranslate } from "@/lingodotdev/server";
import { AddWebhookButton } from "@/modules/integrations/webhooks/components/add-webhook-button";
import { WebhookRowData } from "@/modules/integrations/webhooks/components/webhook-row-data";
import { WebhookTable } from "@/modules/integrations/webhooks/components/webhook-table";
import { WebhookTableHeading } from "@/modules/integrations/webhooks/components/webhook-table-heading";
import { getWebhookSurveys } from "@/modules/integrations/webhooks/lib/surveys";
import { getWebhooks } from "@/modules/integrations/webhooks/lib/webhook";
import { isSurveyVisibilityEnforced } from "@/modules/survey/visibility/lib/gate";
import { GoBackButton } from "@/modules/ui/components/go-back-button";
import { PageContentWrapper } from "@/modules/ui/components/page-content-wrapper";
import { PageHeader } from "@/modules/ui/components/page-header";
import { getWorkspaceAuth } from "@/modules/workspaces/lib/utils";

export const WebhooksPage = async (props: { params: Promise<{ workspaceId: string }> }) => {
  const params = await props.params;
  const t = await getTranslate();

  const { isReadOnly, organization, session, workspace } = await getWorkspaceAuth(params.workspaceId);

  const [webhooks, surveys, surveyVisibilityEnabled] = await Promise.all([
    getWebhooks(workspace.id),
    getWebhookSurveys(workspace.id, session.user.id, organization.id),
    isSurveyVisibilityEnforced(),
  ]);

  const renderAddWebhookButton = () => (
    <AddWebhookButton
      workspaceId={workspace.id}
      surveys={surveys}
      allowInternalUrls={DANGEROUSLY_ALLOW_WEBHOOK_INTERNAL_URLS}
      surveyVisibilityEnabled={surveyVisibilityEnabled}
    />
  );

  return (
    <PageContentWrapper>
      <GoBackButton />
      <PageHeader pageTitle={t("common.webhooks")} cta={!isReadOnly ? renderAddWebhookButton() : <></>} />
      <WebhookTable
        workspaceId={workspace.id}
        webhooks={webhooks}
        surveys={surveys}
        isReadOnly={isReadOnly}
        allowInternalUrls={DANGEROUSLY_ALLOW_WEBHOOK_INTERNAL_URLS}
        surveyVisibilityEnabled={surveyVisibilityEnabled}>
        <WebhookTableHeading />
        {webhooks.map((webhook) => (
          <WebhookRowData
            key={webhook.id}
            webhook={webhook}
            surveys={surveys}
            surveyVisibilityEnabled={surveyVisibilityEnabled}
          />
        ))}
      </WebhookTable>
    </PageContentWrapper>
  );
};

"use client";

import { WebhookIcon } from "lucide-react";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { Webhook } from "@formbricks/database/prisma-browser";
import { TSurvey } from "@formbricks/types/surveys/types";
import { type TUserLocale } from "@formbricks/types/user";
import { WebhookOverviewTab } from "@/modules/integrations/webhooks/components/webhook-overview-tab";
import { WebhookSettingsTab } from "@/modules/integrations/webhooks/components/webhook-settings-tab";
import {
  Dialog,
  DialogBody,
  DialogContent,
